module.exports=[43501,a=>{"use strict";a.s(["j",0,[{id:"inbound",name:"Inbound Voice AI",short:"Answer incoming calls and enquiries instantly.",detail:"The agent picks up, works out why the person is calling and carries the conversation to the configured outcome, instead of sending callers through a menu.",example:[["caller","Hi, I'm calling about the price of your premium plan."],["agent","Happy to help. Is this for a team, or for yourself?"]],stage:"Listen"},{id:"outbound",name:"Outbound Voice AI",short:"Conduct permission-based outbound conversations.",detail:"Follow-ups, reminders, surveys and opted-in content promotion, run according to your consent and communication requirements.",example:[["agent","Hello, this is Aurlynn calling on behalf of Northline about the demo you requested. Is now a good time?"],["caller","Yes, go ahead."]],stage:"Act"},{id:"qualification",name:"Lead Qualification",short:"Ask qualification questions, understand intent and identify opportunities.",detail:"Your own qualification criteria, asked conversationally. Answers are captured as structured fields so sales starts further down the funnel.",example:[["agent","What are you hoping to solve first?"],["caller","We miss a lot of calls after six."]],stage:"Understand"},{id:"booking",name:"Appointment Booking",short:"Connect conversations with scheduling systems.",detail:"Collects preferences, checks availability through your scheduling workflow and confirms the booking, where the integration and permissions are available.",example:[["agent","I have Thursday at 11:00 or Friday at 15:30."],["caller","Thursday works."]],stage:"Act"},{id:"followup",name:"Follow-up Automation",short:"Continue conversations according to business-defined workflows.",detail:"Follow-ups run on your rules: who gets called, when, how many attempts and what happens with the answer.",example:[["agent","Following up on your enquiry from Tuesday. Have you had a chance to decide?"],["caller","Still comparing, call me next week."]],stage:"Act"},{id:"support",name:"Customer Support",short:"Answer common questions and handle repetitive requests.",detail:"Routine questions answered from business-approved information. Anything outside scope is routed to a person with context.",example:[["caller","Can I change my delivery address?"],["agent","Yes. Let me confirm your order number first."]],stage:"Decide"},{id:"data",name:"Data Collection",short:"Capture structured information during calls.",detail:"Names, contact details, requirements and preferences are captured and validated during the conversation, not typed up afterwards.",example:[["agent","Can I confirm your email? That's priya at…"],["caller","Priya dot rao at example dot com."]],stage:"Understand"},{id:"crm",name:"CRM Integration",short:"Update business records based on conversation outcomes.",detail:"Where a CRM integration or API is available, outcomes and captured fields are written to the right record.",example:[["agent","Qualified, meeting booked for Thursday 11:00."],["caller","→ Opportunity updated"]],stage:"Act"},{id:"handoff",name:"Human Handoff",short:"Transfer or escalate conversations when required.",detail:"Rules decide when a person steps in. The human receives the context so the caller does not repeat themselves.",example:[["caller","I need to speak to someone about a contract change."],["agent","I'll bring in a specialist and pass on what you've told me."]],stage:"Escalate"},{id:"multilingual",name:"Multilingual Conversations",short:"Support relevant multilingual customer experiences where configured and supported.",detail:"Voice experiences configured for the audiences and supported languages that matter to your business.",example:[["agent","Would you prefer to continue in another language?"],["caller","Yes, please."]],stage:"Listen"},{id:"analytics",name:"Analytics",short:"Analyze outcomes, trends, conversation patterns and operational insights.",detail:"See what conversations produced, what callers ask most and where workflows can improve.",example:[["agent","Outcomes by workflow, reasons for calling, escalation rate."],["caller","→ Review and refine"]],stage:"Learn"},{id:"workflow",name:"Workflow Automation",short:"Trigger actions in connected business systems.",detail:"A conversation outcome can become a trigger: create a record, schedule a visit, notify a team, start a follow-up.",example:[["agent","Visit confirmed."],["caller","→ Record updated, reminder queued"]],stage:"Act"},{id:"personalization",name:"Personalization",short:"Use approved context to make conversations relevant to the customer.",detail:"Approved customer and business context, within the data and permissions available, so the call does not start from zero.",example:[["agent","Welcome back. Is this about the service booking from last week?"],["caller","Yes, I need to move it."]],stage:"Decide"}],"d",0,["Listen","Understand","Decide","Act","Escalate"]])}];

